# SPDX-FileCopyrightText: Copyright contributors to the vllm projectimport threadingfrom weakref import WeakValueDictionaryimport torchimport torch.distributed as distfrom torch.distributed import ProcessGroupfrom vllm_ascend.distributed.device_communicators.npu_communicator import NPUCommunicatorfrom vllm.logger import init_loggererrorlogger = init_logger(__name__)def all_gather_varlen(self, input_: torch.Tensor, dim: int = -1) -> torch.Tensor:    # 要求除了dim维度以为的其它维度形状完全相同    # 如果要使用group 请用self.device_group 要知道当前rank请用self.rank 要知道world_size请用self.world_size    #tp_rank = get_tensor_model_parallel_rank()tp_rank={tp_rank},    #errorlogger.debug(f"[lqf] all_gather_varlen start:  input.shape={input_.shape}, numel={input_.numel()}, dim={dim}")    if dim < 0:    # Convert negative dim to positive.        dim += input_.dim()    input_size = input_.size()    # step1 把input_的dim维 reshape到第0维     # 例：(a, b, c, d) dim=2 -> (c, a, b, d)    x = torch.movedim(input_, dim, 0)          # 不连续无所谓，后面 reshape 会处理    # step2 allgather获取所有tensor交换后的第0维的大小    local_len = torch.tensor([x.size(0)], dtype=torch.long, device=x.device)    len_buf = torch.empty(self.world_size,                            dtype=torch.long,                            device=x.device)            dist.all_gather_into_tensor(len_buf, local_len, group=self.device_group)    len_list = len_buf.tolist()                     total_len = len_buf.sum().item()    # step3 新建一个全0 tensor output_tensor, device和dtype与input_一致，第0维为全局第0维的大小之和，其余维度和input_的其余维度一致    out_shape = [total_len] + list(x.shape[1:])    output_tensor = torch.zeros(out_shape,                                dtype=x.dtype,                                device=x.device)   # 默认连续    # step4 计算当前rank上 input_的第0维在全局的偏移 将input_的内容cp到output_tensor内(这里是否需要保证output_tensor连续？)    offset = sum(len_list[:self.rank])    end = offset + len_list[self.rank]    output_tensor[offset:end] = x   # 拷贝；x 不连续时 PyTorch 会自动处理    # step5 对output_tensor做全局all_reduce 得到拼接后的结果    dist.all_reduce(output_tensor, group=self.device_group)    # step6 将output_tensor reshape 将第0维reshape回dim维度()    final_shape = (input_size[:dim] +                    (total_len, ) +                    input_size[dim+1:])    output_tensor = output_tensor.reshape(final_shape)    # step7 返回output_tensor    #errorlogger.debug(f"[lqf] all_gather_varlen end: output_tensor.shape={output_tensor.shape}")    return output_tensor